raph 1</p><p>Paragraph 2</p>\n9. If contact email or phone is empty in the brief, do NOT make one up - omit it or use a generic \"Contact us\" link\n10. Only create internal links to pages listed in the Internal Linking section above\n11. NEVER invent fake people, client names, or attributed quotes. No \"Sarah Mitchell, Founder\" or \"James Chen, Marketing Director\". If the brief does not include real testimonials, write company philosophy statements instead and leave name/title fields empty\n12. NEVER invent specific statistics, percentages, or metrics. No \"300% increase\" or \"47 minutes\" or \"42-page report\". Describe the type of outcome without fabricating numbers\n13. NEVER invent fake case studies with named businesses. No \"Brighton Physiotherapy Clinic\" or \"Independent Mortgage Broker\" as if they were real clients. Describe service categories and typical outcomes instead\n14. For testimonial sections: write 2-3 statements in the company's own voice about their values, approach, or commitment. These serve as placeholder content the site owner will replace with real testimonials\n15. For case study sections: describe the types of problems the company solves and the approach they take, without inventing specific clients or results\n16. It is ALWAYS better to be honest and general than specific and fabricated. A real visitor will trust \"We help businesses improve their online presence\" far more than a fake testimonial from an invented person\n\nCRITICAL OUTPUT FORMAT:\n- Output ONLY the requested content\n- Do NOT wrap in code fences or markdown formatting\n- Do NOT add preambles like \"Here's what you asked for...\"\n- Do NOT add post-ambles like \"Hope this helps!\"\n- Start directly with the actual content","response_text":"{\n  \"headline\": \"Reliable Wholesale Fuel Supply for Businesses That Can't Afford Downtime\",\n  \"subheadline\": \"Gas Wholesalers delivers wholesale fuel distribution and natural gas supply to forecourt operators, fleet managers, and industrial buyers across the UK — with transparent pricing, dependable logistics, and a supplier relationship built on accountability.\",\n  \"primary_cta\": \"Request a Supply Quote\",\n  \"primary_cta_url\": \"/contact.html\",\n  \"secondary_cta\": \"Explore Our Services\",\n  \"secondary_cta_url\": \"/services.html\"\n}"}


# chunk 2 runner
IN=/tmp/flywheel_d/test_cases.jsonl
OUT=/tmp/flywheel_d/results.jsonl
rm -f "$OUT"

TOTAL=$(jq -c . "$IN" 2>/dev/null | wc -l)
echo "Processing $TOTAL test cases via /api/chat..."

preflight=$(curl -s -m 60 -X POST http://localhost:21434/api/chat \
    -H 'Content-Type: application/json' \
    -d '{"model":"mistral-small3.1","messages":[{"role":"user","content":"hi"}],"stream":false,"options":{"num_predict":5}}' \
    | jq -r '.message.content // ""')
if [ -z "$preflight" ]; then
    echo "PREFLIGHT FAILED. Aborting."
    exit 1
fi
echo "Preflight ok (preflight returned: '$preflight')"
echo ""

ROW_NUM=0
START_TIME=$(date +%s)

while IFS= read -r row_json; do
    ROW_NUM=$((ROW_NUM + 1))
    log_id=$(echo "$row_json" | jq -r '.id')
    prompt=$(echo "$row_json" | jq -r '.prompt_rendered')
    claude=$(echo "$row_json" | jq -r '.response_text')

    total_elapsed=$(( $(date +%s) - START_TIME ))
    avg_per_case=$((ROW_NUM > 1 ? total_elapsed / (ROW_NUM - 1) : 0))
    remaining=$((avg_per_case * (TOTAL - ROW_NUM + 1)))
    echo "[$ROW_NUM/$TOTAL] (${total_elapsed}s elapsed, ~${remaining}s est remaining) prompt_len=${#prompt}..."

    payload=$(jq -nc --arg m "mistral-small3.1" --arg p "$prompt" \
        '{model:$m, messages:[{role:"user", content:$p}], stream:false, options:{temperature:0.3, num_predict:250}}')

    start=$(date +%s)
    # 1800s = 30 min per call. Absurd, intentional — we want to see real behaviour.
    ollama_raw=$(curl -s -m 1800 -X POST http://localhost:21434/api/chat \
        -H 'Content-Type: application/json' -d "$payload")
    elapsed=$(( $(date +%s) - start ))

    ollama_response=$(echo "$ollama_raw" | jq -r '.message.content // ""')
    prompt_tokens=$(echo "$ollama_raw" | jq -r '.prompt_eval_count // 0')
    output_tokens=$(echo "$ollama_raw" | jq -r '.eval_count // 0')

    if [ -z "$ollama_response" ]; then
        echo "  EMPTY after ${elapsed}s — raw (first 300 chars):"
        echo "$ollama_raw" | head -c 300
        echo ""
        echo "  Capturing ollama-side logs for the last minute..."
        kubectl -n ai-persona-system logs deploy/ollama-adapter --tail=100 --since=60s > /tmp/flywheel_d/ollama_failure_log_${ROW_NUM}.txt
        echo "  Saved to /tmp/flywheel_d/ollama_failure_log_${ROW_NUM}.txt"
        echo "  Aborting."
        break
    fi

    echo "  ok ${elapsed}s prompt_tok=${prompt_tokens} out_tok=${output_tokens} chars=${#ollama_response}"

    jq -nc \
        --arg log_id "$log_id" \
        --arg prompt "$prompt" \
        --arg claude "$claude" \
        --arg ollama "$ollama_response" \
        --argjson elapsed "$elapsed" \
        --argjson prompt_tok "$prompt_tokens" \
        --argjson out_tok "$output_tokens" \
        '{log_id:$log_id, prompt:$prompt, claude_response:$claude, ollama_response:$ollama,
          ollama_latency_s:$elapsed, ollama_prompt_tokens:$prompt_tok, ollama_output_tokens:$out_tok}' \
        >> "$OUT"
done < <(jq -c . "$IN")

echo ""
echo "Done. $(wc -l < "$OUT") results written to $OUT"
echo "Total time: $(( $(date +%s) - START_TIME ))s"


------------------------------------
# chunk 3 - automatic comparison

jq -n --slurpfile results $OUT '
{
  "total_cases": ($results | length),
  "per_case": ($results | map({
    log_id: .log_id,
    claude_valid_json: (try (.claude_response | fromjson | true) catch false),
    ollama_valid_json: (try (.ollama_response | fromjson | true) catch false),
    claude_len: (.claude_response | length),
    ollama_len: (.ollama_response | length),
    ollama_latency_s: .ollama_latency_s,
    ollama_empty: (.ollama_response == "__EMPTY__"),
    # If both are valid JSON, did they produce the same top-level keys?
    claude_keys: (try (.claude_response | fromjson | keys | sort) catch null),
    ollama_keys: (try (.ollama_response | fromjson | keys | sort) catch null),
    keys_match: (
      (try (.claude_response | fromjson | keys | sort) catch null)
      == (try (.ollama_response | fromjson | keys | sort) catch null)
    )
  })),
  "summary": {
    "claude_json_rate": ((($results | map(try (.claude_response | fromjson | true) catch false) | map(select(.)) | length) * 100 / ($results | length))),
    "ollama_json_rate": ((($results | map(try (.ollama_response | fromjson | true) catch false) | map(select(.)) | length) * 100 / ($results | length))),
    "key_match_rate": ((($results | map(
      (try (.claude_response | fromjson | keys | sort) catch null)
      == (try (.ollama_response | fromjson | keys | sort) catch null)
    ) | map(select(.)) | length) * 100 / ($results | length))),
    "ollama_empty_count": (($results | map(select(.ollama_response == "__EMPTY__")) | length)),
    "avg_ollama_latency_s": (($results | map(.ollama_latency_s) | add / length))
  }
}' | jq '{summary, per_case: (.per_case[:5])}'

